suite('factoryReviewVerdict — entry production seams (round-3 rework)', function () {

  var entryModule = loadModule('js/factory/review_verdict_publish.js', makeRequire({
    './review_verdict.js': rvModule,
    './token_usage.js': tokenUsageModule
  }), {});

  function runAction(st, customParams, depsOver) {
    depsOver = depsOver || {};
    var deps = {
      cli_execute_command: function (args) {
        return { output: st.exec(String((args && args.command) || args || '')) };
      },
      file_write: function (p, c) { st.written = st.written || {}; st.written[p] = c; },
      file_read: function () { return null; },
      env: {}
    };
    Object.keys(depsOver).forEach(function (k) { deps[k] = depsOver[k]; });
    return entryModule.action(
      { jobParams: { customParams: Object.assign({
        repo: REPO, number: NUMBER, maxRounds: '2', ghToken: 't',
        config: 'factory-agents/pr_review.json', factoryRoot: STUB_DIR,
        home: STUB_DIR + '/home'
      }, customParams || {}) } }, deps);
  }

  test('production sleepMs is a REAL sleep (the no-op busy-loop blocker)', function () {
    assert.equal(typeof entryModule.productionSleepMs, 'function');
    var t0 = Date.now();
    entryModule.productionSleepMs(25);
    var took = Date.now() - t0;
    assert.ok(took >= 20, 'productionSleepMs(25) must block ~25ms, took ' + took + 'ms');
    var t1 = Date.now();
    entryModule.productionSleepMs(0);
    entryModule.productionSleepMs(-5);
    entryModule.productionSleepMs('garbage');
    assert.ok(Date.now() - t1 < 100, 'non-positive/garbage ms must return immediately');
  });

  test('production sleepMs rides the Java bridge when present (the JSRunner runtime)', function () {
    var sleeps = [];
    var withJava = loadModule('js/factory/review_verdict_publish.js', makeRequire({
      './review_verdict.js': rvModule,
      './token_usage.js': tokenUsageModule
    }), { Java: { type: function (name) {
      assert.equal(name, 'java.lang.Thread');
      return { sleep: function (ms) { sleeps.push(ms); } };
    } } });
    withJava.productionSleepMs(123);
    assert.deepEqual(sleeps, [123]);
  });

  test('action wires the production sleep by default (the poll loop beats 30s)', function () {
    var real = entryModule.productionSleepMs;
    var spied = [];
    entryModule.productionSleepMs = function (ms) { spied.push(ms); };
    try {
      var t = NOW_MS;
      var st = withParser(execStub(baseRules({ rollup: 'PENDING\n' })),
        contractLines({ decision: 'approve' }));
      var r = runAction(st, {}, { clock: function () { return new Date(t += 30000); } });
      assert.equal(r.status, 'ci-timeout');
      assert.ok(spied.length >= 1, 'the default sleep must sit inside the poll loop');
      assert.deepEqual(spied, spied.map(function () { return 30000; }));
    } finally {
      entryModule.productionSleepMs = real;
    }
  });

  test('staged bodies ride a mktemp -d workspace, cleaned up like the sh trap', function () {
    var st = withParser(execStub([['^mktemp -d$', 'out', '/tmp/rvw-mk-4242']]
      .concat(baseRules())), contractLines({ decision: 'rework', escalate: 'true' }),
      'thread summary line\n');
    var r = runAction(st);
    assert.equal(r.status, 'escalated');
    var commentCmds = st.commands.filter(function (c) { return c.indexOf('issue comment') !== -1; });
    assert.equal(commentCmds.length, 1);
    assert.contains(commentCmds[0], '--body-file \'/tmp/rvw-mk-4242/comment.md\'');
    var cleans = st.commands.filter(function (c) { return c.indexOf('rm -rf') === 0; });
    assert.equal(cleans.length, 1);
    assert.contains(cleans[0], 'rm -rf \'/tmp/rvw-mk-4242\'');
    assert.ok(st.commands.indexOf(cleans[0]) > st.commands.indexOf(commentCmds[0]),
      'cleanup runs after the comment is posted (the sh trap ordering)');
  });

  test('the loud no-verdict path still cleans the workspace (finally ≈ the sh trap)', function () {
    var st = withParser(execStub([['^mktemp -d$', 'out', '/tmp/rvw-mk-77']]
      .concat(baseRules())), contractLines({ decision: 'unknown' }));
    var threw = null;
    try { runAction(st); } catch (e) { threw = e; }
    assert.ok(threw, 'the loud path must throw (exit-1 parity)');
    var cleans = st.commands.filter(function (c) { return c.indexOf('rm -rf') === 0; });
    assert.equal(cleans.length, 1);
    assert.contains(cleans[0], 'rm -rf \'/tmp/rvw-mk-77\'');
  });

  test('no mktemp on the transport → unpredictable per-run names, staged files rm -f\'ed', function () {
    var st = withParser(execStub(baseRules()), contractLines({ decision: 'rework', escalate: 'true' }),
      'thread summary line\n');
    var r = runAction(st);
    assert.equal(r.status, 'escalated');
    var commentCmds = st.commands.filter(function (c) { return c.indexOf('issue comment') !== -1; });
    var m = commentCmds[0].match(/--body-file '([^']+)'/);
    assert.ok(m, 'body file staged');
    assert.equal(/^\/tmp\/rv-\d+-\d+-comment\.md$/.test(m[1]), true,
      'unpredictable per-run fallback name, got: ' + m[1]);
    assert.notEqual(m[1], '/tmp/rv-1-comment.md');
    var cleans = st.commands.filter(function (c) { return c.indexOf('rm -f ') === 0; });
    assert.equal(cleans.length, 1);
    assert.contains(cleans[0], m[1]);
  });
});

// ── round-3 rework: module guards ────────────────────────────────────────────

suite('factoryReviewVerdict — applyReviewVerdict guards (round-3 rework)', function () {

  test('non-numeric NUMBER fails loud BEFORE any gh call (the raw jq-splice guard)', function () {
    ['42abc', 'abc', '4 2', "42'; echo pwned", ''].forEach(function (bad) {
      var st = withParser(execStub(baseRules()), contractLines({ decision: 'approve' }));
      var io = ioStub(st);
      var threw = null;
      try { rvModule.applyReviewVerdict(Object.assign(baseOpts(), { number: bad }), io); } catch (e) { threw = e; }
      assert.ok(threw, 'must throw for NUMBER=' + JSON.stringify(bad));
      assert.contains(String(threw && threw.message || threw), 'NUMBER must be numeric');
      assert.equal(st.commands.length, 0, 'zero gh calls for NUMBER=' + JSON.stringify(bad));
    });
  });

  test('token gate precedes the NUMBER guard (the sh checks the token first)', function () {
    var st = execStub([]);
    var io = ioStub(st);
    var r = rvModule.applyReviewVerdict(baseOpts({ ghToken: '', number: 'abc' }), io);
    assert.equal(r.status, 'no-token');
    assert.equal(st.commands.length, 0);
  });

  test('pr-list jq program carries DOUBLE backslashes (pin the README parity claim)', function () {
    var st = withParser(execStub(baseRules()), contractLines({ decision: 'rework' }));
    var io = ioStub(st);
    rvModule.applyReviewVerdict(baseOpts(), io);
    var prList = st.commands.filter(function (c) { return c.indexOf('pr list') !== -1; })[0];
    assert.ok(prList, 'pr list was called');
    assert.contains(prList, '\\\\b(closes|fixes|resolves)\\\\s+#' + NUMBER + '\\\\b');
  });
});

blocks.text:
/**
 * Factory review verdict — the zero-maintainer keystone glue (owner
 * directive 2026-10-13: factory glue moves into dmtools-agents as JS agent
 * code; awf workflows become thin callers).
 *
 * JS port of the awf factory-teammate.yml step «Apply the review verdict
 * (review runs only)» — byte-extracted into scripts/apply-review-verdict.sh
 * by IstiN/dmtools-agentic-workflows#34. Behavior contract is identical:
 *
 *   1. GH_TOKEN missing → warn + skip (labels would not trigger workflows).
 *   2. Fallback sources: the issue's labels, the linked open PR (closes/
 *      fixes/resolves #N in the body, or headRefName ^N[-_.] / gh-0*N$),
 *      the PR's comments+reviews and the issue's comments (a failed fetch
 *      leaves the source file absent — the parser reports `missing`).
 *   3. machineAuthor: workflow input first, then the per-repo
 *      .dmtools/config.js knob (js/common/machineAuthor.js order #2).
 *   4. Parser selection: the unpacked pack's loop/verdict.sh WINS
 *      (versions with the reviewed pack); the legacy
 *      ${FACTORY_ROOT}/setup/review-verdict.sh is the old-pin fallback.
 *   5. The parser emits an eval-safe key=value contract (decision, source,
 *      override, blocking_markers, rounds_done, next_round, escalate,
 *      round_labels, diagnosis). JS parses it line-wise instead of eval'ing
 *      — conformant contracts parse identically; non-conformant output is
 *      IGNORED rather than executed (deliberate hardening, documented).
 *   6. rework + escalate → strip round labels, needs-human (B60205), the
 *      GraphQL review-threads summary comment, done. rework → remove
 *      needs-human, agent:rework + rework-round-N (BFD4F2). approve → the
 *      CI-green gate (≤10 min of 30s polls; red checks refuse the verdict;
 *      all-green → strip labels, pr_approved). No verdict at all → LOUD
 *      failure (gh-305): ::error:: annotation, needs-human, per-source
 *      diagnosis comment, THROW (the sh exits 1 — the step must redden).
 *
 * Error contract mirrors the sh under `bash -e`: gh failures on the
 * load-bearing calls (pr list) propagate; tolerant calls keep the sh's
 * `|| true` / `|| echo ''` semantics (labels, comment sources, rollup,
 * label create, threads fetch).
 *
 * Env/file contract (the sh step's env block; the JSRunner entry reads
 * jobParams.customParams first, these env names as fallback):
 *   GH_TOKEN            presence gates the skip (gh reads it itself)
 *   NUMBER              the review issue
 *   RUN_OUTPUT          the leg's captured run output (default
 *                       .dmtools/run-output.txt)
 *   MACHINE_AUTHOR      workflow input; .dmtools/config.js knob fallback
 *   MAX_ROUNDS          the auto-rework cap (display + parser env)
 *   GITHUB_REPOSITORY   owner/repo
 *   CONFIG              runner config path (basename → pack agent)
 *   FACTORY_ROOT        legacy verdict parser root
 *   HOME                pack cache root (~/.dmtools/packs/…)
 *
 * Pure functions carry no IO: applyReviewVerdict takes { exec, writeFile,
 * readFile, tempFile, clock, sleepMs, log } capturers (factoryState.js
 * convention). exec results are unwrapped ((res.output || res.stdout) ||
 * res — the #893 review lesson); every interpolation goes through
 * shellQuote (token_usage.js); no global gh is touched (tests stub the
 * transport).
 */

var shellQuote = require('./token_usage.js').shellQuote;

var DEFAULT_RUN_OUTPUT = '.dmtools/run-output.txt';
var CI_POLL_MS = 30000;
var CI_DEADLINE_MS = 600000; // ≤10 min, the sh's SECONDS+600

var RED_CHECKS = 'FAILURE|ERROR|CANCELLED|TIMED_OUT|ACTION_REQUIRED|STARTUP_FAILURE|STALE';
var GREEN_CHECKS = 'SUCCESS|SKIPPED|NEUTRAL';

var THREADS_QUERY =
    'query($owner:String!,$name:String!,$number:Int!){repository(owner:$owner,name:$name)' +
    '{pullRequest(number:$number){reviewThreads(first:100){nodes{isResolved path line ' +
    'comments(first:1){nodes{body author{login}}}}}}}}';

var LABELS_JQ = '[.labels[].name] | join(" ")';
var PR_COMMENTS_JQ = '[(.comments // [])[] | {author: (.author.login // ""), body}] + [(.reviews // [])[] | {author: (.author.login // ""), body}]';
var ISSUE_COMMENTS_JQ = '[(.comments // [])[] | {author: (.author.login // ""), body}]';
var ROLLUP_JQ = '.statusCheckRollup[] | if .status and .status != "COMPLETED" then "PENDING" else (.conclusion // .state // "PENDING") end';

// ── pure helpers ─────────────────────────────────────────────────────────────

/**
 * Parses the parser's eval-safe key=value contract. Line-wise; quoted
 * values keep inner spaces; non-conforming lines are IGNORED (never
 * evaluated — safer than the sh's eval, identical for conformant output).
 */
function parseVerdictContract(text) {
    var out = { decision: '', source: '', override: '', blocking_markers: '',
                rounds_done: 0, next_round: 0, escalate: false,
                round_labels: '', diagnosis: '' };
    var lines = String(text == null ? '' : text).split('\n');
    for (var i = 0; i < lines.length; i++) {
        var m = lines[i].match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
        if (!m) continue;
        var v = m[2];
        if (v.length >= 2) {
            var q = v.charAt(0);
            if ((q === '"' || q === "'") && v.charAt(v.length - 1) === q) v = v.substring(1, v.length - 1);
        }
        out[m[1]] = v;
    }
    out.escalate = (out.escalate === true || out.escalate === 'true');
    out.rounds_done = parseInt(out.rounds_done, 10) || 0;
    out.next_round = parseInt(out.next_round, 10) || 0;
    return out;
}

/**
 * machineAuthor resolution order #2 (js/common/machineAuthor.js). NOTE
 * (gh-728): the knob became a comma-separated login list there
 * (`machineAuthor: "ai-teammate,github-actions[bot]"`), but this matcher —
 * deliberately mirroring the spec's `sed -nE` capture ([A-Za-z0-9._-]+,
 * closing quote right after) — resolves SINGLE-login values only; a
 * comma-list matches nothing and MACHINE_AUTHOR stays empty (only *[bot]
 * comment authors trusted). Parity holds by construction; route through
 * machineAuthorLogins-style parsing only if the spec itself is updated.
 */
function resolveMachineAuthor(machineAuthor, io) {
    if (machineAuthor) return machineAuthor;
    try {
        var cfg = io.readFile('.dmtools/config.js');
        if (cfg) {
            var lines = String(cfg).split('\n');
            for (var i = 0; i < lines.length; i++) {
                var m = lines[i].match(/machineAuthor["']?\s*:\s*["']([A-Za-z0-9._-]+)["']/);
                if (m) return m[1];
            }
        }
    } catch (e) { /* unreadable/absent — empty, only *[bot] authors trusted */ }
    return '';
}

/**
 * Parser selection: the unpacked pack's loop/verdict.sh wins (sort -V |
 * tail -1 over the pack cache glob); the legacy FACTORY_ROOT tree is the
 * old-pin fallback. Returns the path; logs the sh's verdict-logic line.
 */
function pickVerdictSh(opts, io) {
    var agent = basenameNoJson(opts.config);
    var glob = 'ls -1 ' + shellQuote(opts.home + '/.dmtools/packs/') + agent +
        '-*/loop/verdict.sh 2>/dev/null | sort -V | tail -1';
    var pack = '';
    try { pack = unwrap(io.exec('bash -c ' + shellQuote(glob))).trim(); } catch (e) { pack = ''; }
    if (pack) {
        io.log('→ verdict logic: pack ' + pack);
        return pack;
    }
    var legacy = (opts.factoryRoot || '') + '/setup/review-verdict.sh';
    io.log('→ verdict logic: legacy tree ' + legacy +
        ' (no ' + agent + ' pack loop/verdict.sh unpacked)');
    return legacy;
}

function basenameNoJson(p) {
    var b = String(p || '').split('/').pop();
    return b.replace(/\.json$/, '');
}

// ── orchestration (capturer-injected) ────────────────────────────────────────

/** The entry's exec unwrap (no trim: body/file paths ride verbatim).
 * An exec result object with EMPTY output is an empty output — not the
 * object itself (the pilot's `(res.output || res.stdout) || res` stringified
 * the object to '[object Object]', which the parity harness caught as the
 * verdict-logic path). */
function unwrap(res) {
    var out = res && (res.output || res.stdout);
    if (out === undefined || out === null) out = (typeo…

/**
 * JSRunner entry — apply the review verdict (review runs only). Thin caller
 * for js/factory/review_verdict.js, the JS port of the awf
 * factory-teammate.yml «Apply the review verdict» step
 * (IstiN/dmtools-agentic-workflows#34 scripts/apply-review-verdict.sh).
 *
 * Invocation (machine-kit / final awf rewire — the sh call becomes):
 *   dmtools run agents/js/factory/run_review_verdict.json
 *
 * Params resolve customParams first, then the sh step's env names, then the
 * sh defaults. See js/factory/README.md for the full env/file contract.
 *
 * Error contract mirrors the sh under `bash -e`: the loud no-verdict path
 * (gh-305) THROWS after leaving needs-human + the diagnosis comment (the sh
 * exits 1 — the step must redden); the parser-invocation transport is
 * unwrapped through the module's canonical `unwrap` (the #893 review
 * lesson — one definition) and never trimmed.
 *
 * Production seams (the sh equivalents):
 *   - sleepMs — the sh's `sleep 30` inside the CI-green poll gate. The
 *     default rides `java.lang.Thread.sleep` on GraalJS (the
 *     aiTeammateTokenUsageReporter.js pattern) and busy-walls on plain
 *     engines; `deps.sleepMs` overrides it in tests. A NO-OP default is
 *     forbidden here: inside a 10-min deadline loop it degenerates into a
 *     `gh pr view` busy-loop (rate-limit burn).
 *   - temp workspace — the sh's `mktemp -d` + `trap 'rm -rf' EXIT`: one
 *     unique per-run directory (created through the transport on the first
 *     staged file), every staged body inside it, best-effort `rm -rf` when
 *     action finishes — throw path included. Without `mktemp` on the
 *     transport the fallback is a randomized per-run file prefix under the
 *     runOutput dir (absolute) or /tmp — never the predictable
 *     /tmp/rv-N-* names, and the staged files are `rm -f`ed on the way out.
 */

var reviewVerdict = require('./review_verdict.js');
var shellQuote = require('./token_usage.js').shellQuote;

/**
 * Env reader for the fallback path (guarded — no java bridge on QuickJS).
 */
function envValue(name) {
    try {
        if (typeof java !== 'undefined' && java && java.lang &&
            java.lang.System && typeof java.lang.System.getenv === 'function') {
            var v = java.lang.System.getenv(name);
            return (v === null || v === undefined) ? '' : String(v);
        }
    } catch (e) { /* no env bridge on this runtime */ }
    return '';
}

/**
 * customParams > env > sh-step defaults. envMap is a test seam.
 */
function resolveParams(params, envMap) {
    var custom = (params && params.jobParams && params.jobParams.customParams) || {};
    function env(name) {
        if (envMap && Object.prototype.hasOwnProperty.call(envMap, name)) return envMap[name];
        return envValue(name);
    }
    function pick(key, envName, dflt) {
        var v = custom[key];
        if (v === undefined || v === null || v === '') v = env(envName);
        if (v === undefined || v === null || v === '') v = dflt;
        return v === undefined || v === null ? '' : String(v);
    }
    return {
        repo: pick('repo', 'GITHUB_REPOSITORY', ''),
        number: pick('number', 'NUMBER', ''),
        runOutput: pick('runOutput', 'RUN_OUTPUT', reviewVerdict.DEFAULT_RUN_OUTPUT || '.dmtools/run-output.txt'),
        machineAuthor: pick('machineAuthor', 'MACHINE_AUTHOR', ''),
        maxRounds: pick('maxRounds', 'MAX_ROUNDS', ''),
        config: pick('config', 'CONFIG', ''),
        factoryRoot: pick('factoryRoot', 'FACTORY_ROOT', ''),
        home: pick('home', 'HOME', ''),
        ghToken: pick('ghToken', 'GH_TOKEN', '')
    };
}

/**
 * The production side of the sleepMs seam — the sh's `sleep 30`. Real
 * Thread.sleep under GraalJS; a wall-clock busy-wait keeps plain engines
 * honest (a no-op here busy-loops the CI-green poll gate).
 */
function productionSleepMs(ms) {
    ms = parseInt(ms, 10) || 0;
    if (ms <= 0) return;
    if (typeof Java !== 'undefined' && Java.type) {
        Java.type('java.lang.Thread').sleep(ms);
        return;
    }
    var end = Date.now() + ms;
    while (Date.now() < end) {}
}

/**
 * The mktemp -d + trap equivalent. The workspace is decided lazily (the
 * first staged file — a no-token run touches nothing): `mktemp -d` through
 * the transport wins; when the transport cannot mktemp, staged files fall
 * back to a randomized per-run prefix under the runOutput dir (absolute)
 * or /tmp — never the old predictable /tmp/rv-N-* names. cleanup() is the
 * trap: rm -rf the dir (or rm -f the fallback files), best-effort.
 */
function makeTempWorkspace(exec, opts) {
    var dir = null;
    var fallbackPrefix = '';
    var staged = [];
    function decide() {
        if (dir !== null) return;
        try { dir = String(exec('mktemp -d') || '').trim(); } catch (e) { dir = ''; }
        if (dir) return;
        var base = (opts.runOutput && opts.runOutput.indexOf('/') === 0)
            ? opts.runOutput.replace(/[^/]*$/, '') : '/tmp/';
        fallbackPrefix = base + 'rv-' + Date.now() + '-' +
            Math.floor(Math.random() * 10000) + '-';
    }
    return {
        tempFile: function (hint) {
            decide();
            var p = dir ? (dir + '/' + hint) : (fallbackPrefix + hint);
            staged.push(p);
            return p;
        },
        cleanup: function () {
            try {
                if (dir) exec('rm -rf ' + shellQuote(dir));
                else if (staged.length) {
                    exec('rm -f' + staged.map(function (p) {
                        return ' ' + shellQuote(p);
                    }).join(''));
                }
            } catch (e) { /* the sh's trap is best-effort */ }
        }
    };
}

/**
 * JSRunner action. deps is a test seam: production resolves the dmtools
 * globals (cli_execute_command / file_write / file_read). The no-verdict
 * path throws (exit-1 parity — the workflow step must redden); every other
 * terminal state returns { status, ... }.
 */
function action(params, deps) {
    deps = deps || {};
    var execRaw = deps.cli_execute_command ||
        (typeof cli_execute_command === 'function' ? cli_execute_command : null);
    var writeRaw = deps.file_write ||
        (typeof file_write === 'function' ? file_write : null);
    var readRaw = deps.file_read ||
        (typeof file_read === 'function' ? file_read : null);
    var opts = resolveParams(params, deps.env);
    // execOut unwrap through the module's canonical definition (no trim:
    // bodies/file paths ride verbatim; an empty-output result object is an
    // empty output — never '[object Object]' as a command string).
    var exec = function (cmd) {
        return reviewVerdict.unwrap(execRaw({ command: cmd }));
    };
    var ws = makeTempWorkspace(exec, opts);
    try {
        var result = reviewVerdict.applyReviewVerdict(opts, {
            exec: exec,
            writeFile: function (p, c) {
                if (!writeRaw) throw new Error('file_write is not available on this runtime');
                return writeRaw(p, c);
            },
            readFile: function (p) {
                if (!readRaw) throw new Error('file_read is not available on this runtime');
                return readRaw({ path: p });
            },
            tempFile: ws.tempFile,
            clock: deps.clock || function () { return new Date(); },
            sleepMs: deps.sleepMs || module.exports.productionSleepMs,
            log: deps.console_log ||
                (typeof console_log === 'function' ? console_log : function (line) { console.log(line); })
        });
        console.log('  ⚖️ review verdict: ' + result.status +
            (result.pr ? ' (PR #' + result.pr + ')' : '') +
            (result.decision ? ' — ' + result.decision : ''));
        return result;
    } finally {
        ws.cleanup();
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        resolveParams: resolveParams,
        envValue: envValue,
        productionSleepMs: productionSleepMs
    };
}

