var DATE_STUB = '#!/usr/bin/env bash\necho 1791885600\n';
var SLEEP_STUB = '#!/usr/bin/env bash\nexit 0\n';

function q(s) { return "'" + String(s).replace(/'/g, "'\\''") + "'"; }

function makeScenario(dir, fx) {
    fs.mkdirSync(dir, { recursive: true });
