    fs.writeFileSync(path.join(bin, 'date'), DATE_STUB);
    fs.writeFileSync(path.join(bin, 'sleep'), SLEEP_STUB);
    ['gh', 'date', 'sleep'].forEach(function (n) {
        fs.chmodSync(path.join(bin, n), 0o755);
