function pickVerdictSh(opts, io) {
    var agent = basenameNoJson(opts.config);
    var glob = 'ls -1 ' + shellQuote(opts.home + '/.dmtools/packs/') + agent +
        '-*/loop/verdict.sh 2>/dev/null | sort -V | tail -1';
    var pack = '';
