// gh rules common to most scenarios: pr list → PR 7 linked; rollup green.
function baseRules(over) {
    over = over || {};
    return [
        ["bash -c 'ls -1", 'out', STUB_DIR + '/home/.dmtools/packs/pr_review-2.0.0/loop/verdict.sh\n'],
