        cleanup: function () {
            try {
                if (dir) exec('rm -rf ' + shellQuote(dir));
                else if (staged.length) {
                    exec('rm -f' + staged.map(function (p) {
                        return ' ' + shellQuote(p);
                    }).join(''));
