    '    ;;',
    '  esac',
    '  apply_jq < "$SCENARIO_DIR/pr_view.json"',
    '  exit 0',
    'fi',
    'if [ "$1" = pr ] && [ "$2" = list ]; then',
    '  apply_jq < "$SCENARIO_DIR/pr_list.json"',
