    'fi',
    'if [ "$1" = pr ] && [ "$2" = edit ]; then',
    '  { printf \'pr-edit\'; for a in "$@"; do printf \' [%s]\' "$a"; done; printf \'\\n\'; } >> "$SCENARIO_DIR/gh_calls.log"',
