    '        *) printf \'{"statusCheckRollup":[{"status":"COMPLETED","conclusion":"SUCCESS"}]}\\n\' ;;',
    '      esac',
    '    else',
    '      printf \'{"statusCheckRollup":[{"status":"IN_PROGRESS","conclusion":null}]}\\n\'',
    '    fi | apply_jq',
